import collections
import matplotlib.pyplot as plt

def task_func(data):
    if not data:
        return None

    scores_by_student = collections.defaultdict(list)

    for record in data:
        if record is None:
            continue
        for student, score in record.items():
            if score is None:
                continue
            if score < 0:
                raise ValueError("Negative scores are not allowed")
            scores_by_student[student].append(score)

    if not scores_by_student:
        return None

    students = list(scores_by_student.keys())
    averages = [
        sum(scores_by_student[student]) / len(scores_by_student[student])
        for student in students
    ]

    colors = ["red", "yellow", "green", "blue", "purple"]
    bar_colors = [colors[i % len(colors)] for i in range(len(students))]

    _, ax = plt.subplots()
    ax.bar(students, averages, color=bar_colors)
    ax.set_title("Average Student Scores")
    ax.set_xlabel("Student")
    ax.set_ylabel("Average Score")

    return ax

